import numpy as np
import matplotlib.pyplot as plt
x = np.array([1.0, 2.0, 3.0, 4.5, 6.0])
y = np.array([18.0, 25.0, 34.0, 44.0, 55.0])

def loss(w):
    return np.mean((w * x - y) ** 2)

def grad(w):
    return np.mean(2 * (w * x - y) * x)


w=0.; history=[]
for _ in range(40):
 w-=.01*grad(w)
 history.append(float(loss(w)))
plt.plot(range(1,41),history); plt.xlabel("шаг"); plt.ylabel("MSE")
steps_to_30=next(i for i,m in enumerate(history,1) if m<30)
